@Override
public InteractionResult useOn(UseOnContext context) {
    Player player = context.getPlayer();
    if (player == null) return InteractionResult.FAIL;
    InteractionHand hand = context.getHand();
    Direction facing = context.getClickedFace();
    ItemStack stack = player.getItemInHand(hand);
    BlockPos pos = context.getClickedPos();
    Level world = context.getLevel();
    if (world.isClientSide) {
        return InteractionResult.SUCCESS;
    } else if (!player.mayUseItemAt(pos.relative(facing), facing, stack)) {
        return InteractionResult.FAIL;
    }
    Entity entity = spawnCreature((ServerLevel) world, new EntityBabyFoliaath(EntityHandler.BABY_FOLIAATH.get(), world), pos.getX(), pos.getY() + 1, pos.getZ());
    if (entity != null) {
        if (entity instanceof LivingEntity && stack.has(DataComponents.CUSTOM_NAME)) {
            entity.setCustomName(stack.getHoverName());
        }
        if (!player.isCreative()) {
            stack.shrink(1);
        }
    }
    return InteractionResult.SUCCESS;
}

public Entity spawnCreature(ServerLevelAccessor world, Mob entity, double x, double y, double z) {
    if (entity != null) {
        entity.moveTo(x + 0.5, y, z + 0.5, world.getLevel().random.nextFloat() * 360 - 180, 0);
        entity.yHeadRot = entity.getYRot();
        entity.yBodyRot = entity.getYRot();
        entity.finalizeSpawn(world, world.getCurrentDifficultyAt(entity.blockPosition()), MobSpawnType.MOB_SUMMONED, null);
        if (!entity.checkSpawnRules(world, MobSpawnType.MOB_SUMMONED)) {
            return null;
        }
        world.addFreshEntity(entity);
    }
    return entity;
}

@Override
public boolean checkSpawnRules(LevelAccessor world, MobSpawnType reason) {
    if (world.isUnobstructed(this) && world.noCollision(this) && !world.containsAnyLiquid(getBoundingBox())) {
        BlockPos ground = new BlockPos(
                Mth.floor(getX()),
                Mth.floor(getBoundingBox().minY) - 1,
                Mth.floor(getZ())
        );

        BlockState block = world.getBlockState(ground);

        if (block.getBlock() == Blocks.GRASS_BLOCK || block.is(BlockTags.DIRT) || block.is(BlockTags.LEAVES)) {
            playSound(SoundEvents.GRASS_HIT, 1, 0.8F);
            return true;
        }
    }
    return false;
}

@Override
protected void registerGoals() {
    super.registerGoals();
