@Override // Copied from Mob class file
public void checkDespawn() {
    if (EventHooks.checkMobDespawn(this)) return;
    if (this.level().getDifficulty() == Difficulty.PEACEFUL && this.shouldDespawnInPeaceful()) {
        this.discard();
    } else if (!this.isPersistenceRequired() && !this.requiresCustomPersistence()) {
        Entity entity = this.level().getNearestPlayer(this, -1);

        if (entity != null) {
            double distance = entity.distanceToSqr(this);
            int despawnDistance = getDespawnDistance();
            int despawnRadius = despawnDistance * despawnDistance;

            if (distance > despawnRadius && this.removeWhenFarAway(distance)) {
                this.discard();
            }

            int noDespawnDistance = getNoDespawnDistance();
            int noDespawnRadius = noDespawnDistance * noDespawnDistance;

            if (this.noActionTime > 600 && this.random.nextInt(800) == 0 && distance > noDespawnRadius && this.removeWhenFarAway(distance)) {
                this.discard();
            } else if (distance < noDespawnRadius) {
                this.noActionTime = 0;
            }
        }
    } else {
        this.noActionTime = 0;
    }
}

@Override
public void tick() {
    super.tick();
    if (getAnimation() != NO_ANIMATION) {
        animationTick++;
        if (level().isClientSide && animationTick >= animation.getDuration()) {
            setAnimation(NO_ANIMATION);
        }
    }
}

@Override
public Animation getAnimation() {
    return this.animation;
}

@Override
public void setAnimation(Animation animation) {
    if (animation == NO_ANIMATION) {
        onAnimationFinish(this.animation);
    }
    this.animation = animation;
    setAnimationTick(0);
}

package com.bobmowzie.mowziesmobs.server.ai.animation;

import com.bobmowzie.mowziesmobs.server.entity.MowzieEntity;
import com.ilexiconn.llibrary.server.animation.Animation;
import com.ilexiconn.llibrary.server.animation.IAnimatedEntity;

public class AnimationBabyFoliaathEatAI<T extends MowzieEntity & IAnimatedEntity> extends SimpleAnimationAI<T> {
    public AnimationBabyFoliaathEatAI(T entity, Animation animation) {
        super(entity, animation);
    }
}

@Override
protected boolean test(Animation animation) {
    return animation == this.animation;
}

@Override
public boolean canUse() {
    return this.test(this.entity.getAnimation());
}

@Override
public boolean canContinueToUse() {
    return this.test(this.entity.getAnimation()) && this.entity.getAnimationTick() < this.entity.getAnimation().getDuration();
}

@Override
public void stop() {
    if (this.test(this.entity.getAnimation())) {
        AnimationHandler.INSTANCE.sendAnimationMessage(this.entity, IAnimatedEntity.NO_ANIMATION);
    }
}

